    if name != INTERNAL_NAME:
        return None
    query_flags = struct.unpack('!H', packet[2:4])[0]
    flags = 0x8400 | (query_flags & 0x0100)
    if qtype == 1 and qclass == 1:
        header = packet[:2] + struct.pack('!HHHHH', flags, 1, 1, 0, 0)
        answer = '\xc0\x0c' + struct.pack('!HHIH', 1, 1, 300, 4) + socket.inet_aton(INTERNAL_IP)
        return header + packet[12:question_end] + answer
    header = packet[:2] + struct.pack('!HHHHH', flags, 1, 0, 0, 0)
    return header + packet[12:question_end]

