    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        sock.settimeout(3)
        sock.sendto(packet, UPSTREAM)
        return sock.recvfrom(65535)[0]
    finally:
        sock.close()

