                response = forward_udp(packet)
            out_sock.sendto(response, self.client_address)
        except Exception as exc:
            print('UDP error from %r: %s' % (self.client_address, exc))

class TCPHandler(SocketServer.BaseRequestHandler):
    def recvn(self, count):
        parts = []
        remaining = count
        while remaining:
            part = self.request.recv(remaining)
            if not part:
                raise ValueError('short TCP DNS request')
            parts.append(part)
            remaining -= len(part)
        return ''.join(parts)

